const response = pm.response.json();
const items = response.data;

const incompleteItems = [];

items.forEach(function (item) {
    const missingDetails = [];

    if (!item.item_name) {
        missingDetails.push('Item Name');
    }

    if (!item.item_code) {
        missingDetails.push('Item Code');
    }

    if (!item.item_group) {
        missingDetails.push('Item Group');
    }

    if (!item.stock_uom) {
        missingDetails.push('Stock UOM');
    }

    if (missingDetails.length > 0) {
        incompleteItems.push({
            item_id: item.name,
            missing_details: missingDetails
        });
    }
});

pm.test('The following data are missing: Item Name, Item Code, stock_uom', function () {
    pm.expect(true).to.be.true;
});

pm.environment.set(
    'incomplete_item_records',
    JSON.stringify(incompleteItems)
);

